create extension if not exists pgcrypto;
create extension if not exists postgis with schema extensions;
create type public.staff_role as enum ('COORDINATOR','ADMIN');
create type public.request_status as enum ('NEW','ASSIGNED','IN_PROGRESS','WAITING','RESOLVED','CLOSED');
create type public.step_status as enum ('TODO','IN_PROGRESS','DONE');
create type public.review_status as enum ('PENDING','VERIFIED','REJECTED');
create table public.profiles(id uuid primary key references auth.users on delete cascade, alias varchar(80), country varchar(80), city varchar(120), can_message boolean not null default true, can_call boolean not null default false, contact_window varchar(120), external_contact varchar(200), deletion_requested_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.staff_roles(user_id uuid not null references auth.users on delete cascade, role public.staff_role not null, granted_by uuid references auth.users, granted_at timestamptz not null default now(), primary key(user_id,role));
create sequence public.case_number_seq start 1000;
create table public.help_requests(id uuid primary key default gen_random_uuid(),case_number bigint not null default nextval('public.case_number_seq') unique,owner_id uuid not null references auth.users,category varchar(40) not null,country varchar(80) not null,city varchar(120) not null,description varchar(5000) not null,urgency varchar(10) not null check(urgency in('NORMAL','SOON','URGENT')),status public.request_status not null default 'NEW',can_message boolean not null default true,can_call boolean not null default false,contact_window varchar(120) not null default '',external_contact varchar(200) not null default '',closed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.case_assignments(id uuid primary key default gen_random_uuid(),help_request_id uuid not null references public.help_requests on delete cascade,coordinator_id uuid not null references auth.users,assigned_by uuid not null references auth.users,reason varchar(500) not null,assigned_at timestamptz not null default now(),revoked_at timestamptz,revoked_by uuid references auth.users,revoke_reason varchar(500),unique nulls not distinct(help_request_id,revoked_at));
create table public.messages(id uuid primary key default gen_random_uuid(),help_request_id uuid not null references public.help_requests on delete cascade,author_id uuid not null references auth.users,client_nonce uuid not null,body varchar(4000) not null check(length(trim(body))>0),created_at timestamptz not null default now(),unique(author_id,client_nonce));
create table public.organizations(id uuid primary key default gen_random_uuid(),name varchar(200) not null,description varchar(2000),source_url varchar(1000),review_status public.review_status not null default 'PENDING',verified_at timestamptz,published_at timestamptz,created_at timestamptz not null default now());
create table public.service_locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,name varchar(200) not null,categories text[] not null default '{}',country varchar(80) not null,city varchar(120) not null,address_public varchar(500),is_confidential_address boolean not null default false,location extensions.geography(point,4326),languages text[] not null default '{}',formats text[] not null default '{}',cost_type varchar(20) not null check(cost_type in('FREE','PAID','MIXED','UNKNOWN')),opening_hours varchar(1000),contact_public varchar(1000),source_url varchar(1000),review_status public.review_status not null default 'PENDING',verified_at timestamptz,published_at timestamptz,last_verified_at timestamptz,created_at timestamptz not null default now(),check(not is_confidential_address or (address_public is null and location is null)));
create index service_locations_geo_idx on public.service_locations using gist(location);
create table public.support_steps(id uuid primary key default gen_random_uuid(),help_request_id uuid not null references public.help_requests on delete cascade,title varchar(500) not null,responsible varchar(120) not null,due_at date,status public.step_status not null default 'TODO',organization_id uuid references public.organizations,created_by uuid not null references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.volunteer_offers(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users,category varchar(80) not null,city varchar(120) not null,online boolean not null default false,description varchar(3000) not null,contact_method varchar(200) not null,review_status public.review_status not null default 'PENDING',created_at timestamptz not null default now());
create table public.consents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,help_request_id uuid references public.help_requests on delete cascade,kind varchar(40) not null check(kind in('REQUEST_PROCESSING','EXTERNAL_CONTACT','IDENTITY_INTEGRATION')),text_version varchar(80) not null,accepted_at timestamptz not null default now(),revoked_at timestamptz);
create table public.audit_events(id bigint generated always as identity primary key,actor_id uuid references auth.users,action varchar(80) not null,object_type varchar(40) not null,object_id uuid,reason varchar(500),created_at timestamptz not null default now());
create table public.identity_links(id uuid primary key default gen_random_uuid(),local_user_id uuid not null references auth.users,provider varchar(80) not null,external_subject varchar(255) not null,verified_at timestamptz not null,consent_id uuid not null references public.consents,revoked_at timestamptz,unique(provider,external_subject));
create index requests_owner_idx on public.help_requests(owner_id,created_at desc);create index assignments_active_idx on public.case_assignments(help_request_id,coordinator_id) where revoked_at is null;create index messages_page_idx on public.messages(help_request_id,created_at desc,id);create index steps_case_idx on public.support_steps(help_request_id,created_at);
create function public.is_admin(uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.staff_roles where user_id=uid and role='ADMIN')$$;
create function public.is_active_coordinator(case_id uuid,uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.case_assignments where help_request_id=case_id and coordinator_id=uid and revoked_at is null)$$;
revoke all on function public.is_admin(uuid),public.is_active_coordinator(uuid,uuid) from public;grant execute on function public.is_admin(uuid),public.is_active_coordinator(uuid,uuid) to authenticated;
create function public.can_access_case(case_id uuid,uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.help_requests h where h.id=case_id and (h.owner_id=uid or public.is_active_coordinator(case_id,uid)))$$;
revoke all on function public.can_access_case(uuid,uuid) from public;grant execute on function public.can_access_case(uuid,uuid) to authenticated;
create function public.create_help_request(payload jsonb,consent_version text) returns uuid language plpgsql security definer set search_path='' as $$declare rid uuid;begin if auth.uid() is null then raise exception 'authentication required';end if; if length(payload->>'description') not between 20 and 5000 then raise exception 'invalid description';end if;if (select count(*) from public.help_requests where owner_id=auth.uid() and created_at>now()-interval '1 hour')>=5 then raise exception 'rate limit';end if;insert into public.help_requests(owner_id,category,country,city,description,urgency,can_message,can_call,contact_window,external_contact) values(auth.uid(),payload->>'category',payload->>'country',payload->>'city',payload->>'description',payload->>'urgency',coalesce((payload->>'can_message')::boolean,true),coalesce((payload->>'can_call')::boolean,false),coalesce(payload->>'contact_window',''),coalesce(payload->>'external_contact','')) returning id into rid;insert into public.consents(user_id,help_request_id,kind,text_version) values(auth.uid(),rid,'REQUEST_PROCESSING',consent_version);return rid;end$$;
revoke all on function public.create_help_request(jsonb,text) from public;grant execute on function public.create_help_request(jsonb,text) to authenticated;
create function public.enforce_message() returns trigger language plpgsql security definer set search_path='' as $$begin new.author_id:=auth.uid();if not public.can_access_case(new.help_request_id,auth.uid()) then raise exception 'access denied';end if;if (select count(*) from public.messages where author_id=auth.uid() and created_at>now()-interval '1 minute')>=20 then raise exception 'rate limit';end if;return new;end$$;
create trigger messages_author before insert on public.messages for each row execute function public.enforce_message();
create view public.published_service_locations with (security_invoker=true) as select l.id,o.name organization_name,l.name,l.categories,l.country,l.city,l.address_public,l.languages,l.formats,l.cost_type,l.opening_hours,l.contact_public,l.last_verified_at from public.service_locations l join public.organizations o on o.id=l.organization_id where l.review_status='VERIFIED' and l.published_at is not null and o.review_status='VERIFIED' and o.published_at is not null and not l.is_confidential_address;
create function public.nearby_service_locations(user_lat float,user_lon float,radius_m int default 50000,result_limit int default 50,result_offset int default 0) returns table(id uuid,organization_name text,name text,city text,address_public text,languages text[],formats text[],cost_type text,distance_meters float,contact_public text,opening_hours text) language sql stable security definer set search_path='' as $$select l.id,o.name::text,l.name::text,l.city::text,l.address_public::text,l.languages,l.formats,l.cost_type::text,extensions.st_distance(l.location,extensions.st_setsrid(extensions.st_makepoint(user_lon,user_lat),4326)::extensions.geography),l.contact_public::text,l.opening_hours::text from public.service_locations l join public.organizations o on o.id=l.organization_id where l.review_status='VERIFIED' and l.published_at is not null and o.review_status='VERIFIED' and o.published_at is not null and not l.is_confidential_address and l.location is not null and extensions.st_dwithin(l.location,extensions.st_setsrid(extensions.st_makepoint(user_lon,user_lat),4326)::extensions.geography,least(greatest(radius_m,100),100000)) order by l.location operator(extensions.<->) extensions.st_setsrid(extensions.st_makepoint(user_lon,user_lat),4326)::extensions.geography limit least(greatest(result_limit,1),100) offset greatest(result_offset,0)$$;
revoke all on function public.nearby_service_locations(float,float,int,int,int) from public;grant execute on function public.nearby_service_locations(float,float,int,int,int) to anon,authenticated;
-- API lockdown: grants are column-scoped where immutable ownership/service fields matter.
revoke all on all tables in schema public from anon,authenticated;revoke all on all sequences in schema public from anon,authenticated;
alter table public.profiles enable row level security;alter table public.staff_roles enable row level security;alter table public.help_requests enable row level security;alter table public.case_assignments enable row level security;alter table public.messages enable row level security;alter table public.support_steps enable row level security;alter table public.organizations enable row level security;alter table public.service_locations enable row level security;alter table public.volunteer_offers enable row level security;alter table public.consents enable row level security;alter table public.audit_events enable row level security;alter table public.identity_links enable row level security;
grant select(alias,country,city,can_message,can_call,contact_window,external_contact,deletion_requested_at,created_at,updated_at),update(alias,country,city,can_message,can_call,contact_window,external_contact,deletion_requested_at) on public.profiles to authenticated;
create policy profile_self on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
grant select on public.help_requests to authenticated;create policy case_read on public.help_requests for select to authenticated using(public.can_access_case(id));
grant select,insert(body,help_request_id,client_nonce) on public.messages to authenticated;create policy message_read on public.messages for select to authenticated using(public.can_access_case(help_request_id));create policy message_insert on public.messages for insert to authenticated with check(public.can_access_case(help_request_id));
grant select on public.support_steps to authenticated;create policy step_read on public.support_steps for select to authenticated using(public.can_access_case(help_request_id));
grant select on public.volunteer_offers to authenticated;grant insert(category,city,online,description,contact_method) on public.volunteer_offers to authenticated;create policy offer_self_read on public.volunteer_offers for select to authenticated using(owner_id=auth.uid() or public.is_admin());create policy offer_self_insert on public.volunteer_offers for insert to authenticated with check(owner_id=auth.uid());
grant select on public.organizations,public.service_locations to anon,authenticated;create policy org_public on public.organizations for select to anon,authenticated using(review_status='VERIFIED' and published_at is not null);create policy loc_public on public.service_locations for select to anon,authenticated using(review_status='VERIFIED' and published_at is not null and not is_confidential_address);
grant select on public.published_service_locations to anon,authenticated;
create policy consent_self_read on public.consents for select to authenticated using(user_id=auth.uid());
create function public.assign_case(case_id uuid,new_coordinator uuid,reason_text text) returns void language plpgsql security definer set search_path='' as $$begin if not public.is_admin() then raise exception 'admin required';end if;if length(trim(reason_text))<3 then raise exception 'reason required';end if;if not exists(select 1 from public.staff_roles where user_id=new_coordinator and role in('COORDINATOR','ADMIN')) then raise exception 'staff role required';end if;update public.case_assignments set revoked_at=now(),revoked_by=auth.uid(),revoke_reason='reassigned: '||left(reason_text,450) where help_request_id=case_id and revoked_at is null;insert into public.case_assignments(help_request_id,coordinator_id,assigned_by,reason)values(case_id,new_coordinator,auth.uid(),reason_text);update public.help_requests set status=case when status='NEW' then 'ASSIGNED' else status end,updated_at=now() where id=case_id;insert into public.audit_events(actor_id,action,object_type,object_id,reason)values(auth.uid(),'CASE_ASSIGNED','help_request',case_id,left(reason_text,500));end$$;
create function public.revoke_case_assignment(case_id uuid,reason_text text) returns void language plpgsql security definer set search_path='' as $$begin if not public.is_admin() then raise exception 'admin required';end if;update public.case_assignments set revoked_at=now(),revoked_by=auth.uid(),revoke_reason=left(reason_text,500) where help_request_id=case_id and revoked_at is null;if not found then raise exception 'no active assignment';end if;insert into public.audit_events(actor_id,action,object_type,object_id,reason)values(auth.uid(),'CASE_ACCESS_REVOKED','help_request',case_id,left(reason_text,500));end$$;
create function public.change_case_status(case_id uuid,new_status public.request_status) returns void language plpgsql security definer set search_path='' as $$declare old_status public.request_status;begin select status into old_status from public.help_requests where id=case_id and public.can_access_case(id) for update;if old_status is null then raise exception 'access denied';end if;if auth.uid()=(select owner_id from public.help_requests where id=case_id) and new_status<>'CLOSED' then raise exception 'owner may only close';end if;if not ((old_status='NEW' and new_status in('ASSIGNED','CLOSED'))or(old_status='ASSIGNED' and new_status in('IN_PROGRESS','WAITING','CLOSED'))or(old_status='IN_PROGRESS' and new_status in('WAITING','RESOLVED','CLOSED'))or(old_status='WAITING' and new_status in('IN_PROGRESS','RESOLVED','CLOSED'))or(old_status='RESOLVED' and new_status in('IN_PROGRESS','CLOSED'))) then raise exception 'invalid transition';end if;update public.help_requests set status=new_status,closed_at=case when new_status='CLOSED' then now() end,updated_at=now() where id=case_id;end$$;
revoke all on function public.assign_case(uuid,uuid,text),public.revoke_case_assignment(uuid,text),public.change_case_status(uuid,public.request_status) from public;grant execute on function public.assign_case(uuid,uuid,text),public.revoke_case_assignment(uuid,text),public.change_case_status(uuid,public.request_status) to authenticated;
alter publication supabase_realtime add table public.messages;
create function public.assignment_queue(queue_limit int default 50,queue_offset int default 0) returns table(id uuid,case_number bigint,category text,city text,urgency text,status public.request_status,created_at timestamptz) language sql stable security definer set search_path='' as $$select h.id,h.case_number,h.category::text,h.city::text,h.urgency::text,h.status,h.created_at from public.help_requests h where public.is_admin() order by case when h.urgency='URGENT' then 0 when h.urgency='SOON' then 1 else 2 end,h.created_at limit least(greatest(queue_limit,1),100) offset greatest(queue_offset,0)$$;
revoke all on function public.assignment_queue(int,int) from public;grant execute on function public.assignment_queue(int,int) to authenticated;
